23	function parseValue(raw: string, params: unknown[], cursor: { i: number }): unknown {
24	  if (raw === '?') return params[cursor.i++];
25	  if (/^'.*'$/.test(raw)) return raw.slice(1, -1);
26	  if (/^-?\d+(\.\d+)?$/.test(raw)) return Number(raw);
27	  return raw;
28	}
