3	import { summarizeClaimWithBedrock } from '../services/summarization';
4	import { validate } from '../middleware/validate';
5	
6	export const claimsRouter = Router();
7	
8	claimsRouter.post(
9	  '/submit',
10	  validate([
11	    { field: 'claimId', required: true },
12	    { field: 'policyId', required: true },
13	    { field: 'amount', required: true },
14	  ]),
15	  (req, res) => {
16	    const { claimId, policyId, amount, ssn, patientName, condition } = req.body;
17	
18	    const policy = getPolicyById(policyId);
19	    if (!policy || !policy.active) {
20	      res.status(404).json({ error: 'Policy not found or inactive' });
21	      return;
22	    }
23	
24	    const approved = amount <= policy.premium * 10;
25	    const status = approved ? 'approved' : 'denied';
26	
27	    const summaryResult = summarizeClaimWithBedrock({ claimId, ssn, patientName, condition });
28	
29	    try {
30	      updateClaimStatus(claimId, status);
31	    } catch {
32	      // existing behavior — not part of this task
33	    }
34	
35	    res.json({
36	      claimId,
37	      status,
38	      summary: summaryResult.summary,
39	      policy,
40	    });
41	  }
42	);

1	import type { Request, Response, NextFunction } from 'express';
2	
3	export interface FieldRule {
4	  field: string;
5	  required: boolean;
6	  pattern?: RegExp;
7	}
8	
9	export function validate(rules: FieldRule[]) {
10	  return (req: Request, res: Response, next: NextFunction) => {
11	    for (const rule of rules) {
12	      const value = req.body[rule.field];
13	      if (rule.required && (value === undefined || value === null || value === '')) {
14	        res.status(400).json({ error: `Missing required field: ${rule.field}` });
15	        return;
16	      }
17	      if (value !== undefined && rule.pattern && !rule.pattern.test(String(value))) {
18	        res.status(400).json({ error: `Invalid format for field: ${rule.field}` });
19	        return;
20	      }
21	    }
22	    next();
23	  };
24	}

1	const PII_FIELDS = ['ssn', 'patientName', 'holderName'];
2	
3	export function redact<T extends Record<string, any>>(payload: T): Record<string, any> {
4	  const clone: Record<string, any> = { ...payload };
5	  for (const field of PII_FIELDS) {
6	    if (field in clone) clone[field] = '[REDACTED]';
7	  }
8	  return clone;
9	}

